-- LibraryCorpus: Published corpus in the library catalog.
CREATE TABLE IF NOT EXISTS corpora (
    uid TEXT NOT NULL,
    name TEXT NOT NULL,
    language TEXT,
    type TEXT,
    category TEXT,
    version TEXT NOT NULL,
    available BOOLEAN NOT NULL DEFAULT true,
    PRIMARY KEY (uid)
);

-- License: Licence catalog entry.
CREATE TABLE IF NOT EXISTS licences (
    id TEXT NOT NULL,
    title TEXT NOT NULL,
    url TEXT,
    domain_content BOOLEAN NOT NULL DEFAULT false,
    domain_data BOOLEAN NOT NULL DEFAULT false,
    domain_software BOOLEAN NOT NULL DEFAULT false,
    family TEXT,
    maintainer TEXT,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired', 'superseded')),
    is_generic BOOLEAN NOT NULL DEFAULT false,
    legacy_ids TEXT[],
    od_conformance TEXT CHECK (od_conformance IN ('not reviewed', 'approved', 'rejected')),
    osd_conformance TEXT CHECK (osd_conformance IN ('not reviewed', 'approved', 'rejected')),
    full_text TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ,
    PRIMARY KEY (id)
);

-- Organization: Organization or institution owning projects.
CREATE TABLE IF NOT EXISTS organizations (
    id UUID NOT NULL,
    name TEXT NOT NULL,
    website TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (id)
);

-- User: Directory user with profile fields.
CREATE TABLE IF NOT EXISTS user_directory (
    id UUID NOT NULL,
    username TEXT NOT NULL UNIQUE,
    email TEXT NOT NULL UNIQUE,
    name TEXT,
    avatar_url TEXT,
    vocation TEXT,
    tradition TEXT,
    languages TEXT,
    affiliation TEXT,
    website TEXT,
    bio TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ,
    PRIMARY KEY (id)
);

-- Project: A scholarly project; scriptural types require languages (FR-006), categorized types require a category (FR-007).
CREATE TABLE IF NOT EXISTS projects (
    id UUID NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'started', 'ready-for-review', 'published', 'failed')),
    type TEXT CHECK (type IN ('bible', 'commentary', 'lexicon', 'biography', 'review', 'manuscript', 'tanakh', 'quran', 'apocrypha', 'regular')),
    language TEXT[],
    category TEXT CHECK (category IN ('biblical', 'religious', 'literary', 'historical', 'paratext')),
    creator_id UUID NOT NULL REFERENCES user_directory (id),
    organization_id UUID REFERENCES organizations (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (id)
);

-- ProjectCorpusLink: Library corpora loaded alongside a project's dataset.
CREATE TABLE IF NOT EXISTS project_corpora (
    project_id UUID NOT NULL REFERENCES projects (id),
    corpus_id TEXT NOT NULL REFERENCES corpora (uid),
    linked_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (project_id, corpus_id)
);

-- ProjectLicense: Licence attached to a project. agreed_at pairs with agreed_by_user_id under a check constraint; pending exactly when agreed_at is null.
CREATE TABLE IF NOT EXISTS project_licences (
    project_id UUID NOT NULL REFERENCES projects (id),
    licence_id TEXT NOT NULL REFERENCES licences (id),
    agreed_at TIMESTAMPTZ,
    agreed_by_user_id UUID REFERENCES user_directory (id),
    PRIMARY KEY (project_id, licence_id)
);

-- CorpusDocument: Corpus archive imported into a project, with conversion metadata from the corpora-py contract.
CREATE TABLE IF NOT EXISTS corpus_documents (
    id UUID NOT NULL,
    project_id UUID NOT NULL REFERENCES projects (id),
    name TEXT NOT NULL,
    source TEXT NOT NULL CHECK (source IN ('upload', 'huggingface')),
    path TEXT NOT NULL,
    filename TEXT,
    job_id TEXT,
    uploaded_at TIMESTAMPTZ NOT NULL,
    corpus_type TEXT CHECK (corpus_type IN ('text', 'web', 'parallel', 'speech', 'docs')),
    source_format TEXT,
    licence TEXT,
    language TEXT,
    size_bytes BIGINT,
    docs_count BIGINT,
    nodes BIGINT,
    words BIGINT,
    status TEXT CHECK (status IN ('uploaded', 'converted')),
    converted_at TIMESTAMPTZ,
    description TEXT,
    toc JSONB,
    PRIMARY KEY (id)
);

-- CorpusCommit: One commit from the corpus' nested .git, newest first.
CREATE TABLE IF NOT EXISTS corpus_commits (
    id UUID NOT NULL,
    document_id UUID NOT NULL REFERENCES corpus_documents (id),
    sha TEXT NOT NULL,
    message TEXT NOT NULL,
    author_name TEXT,
    author_email TEXT,
    branch TEXT,
    committed_at TIMESTAMPTZ,
    PRIMARY KEY (id)
);
